insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 1, 'An overall coefficient is quoted in Btu per hour per square foot per degF. What is the quantity that unit describes?', '["The rate at which the produced fluid surrenders the heat it is carrying, which is why a heavier crude with a larger specific heat comes back with a lower coefficient on the same pipe.", "How fast heat crosses the wall stack for every degree of difference across it, referred to a named area.", "The heat the line loses in an hour, so that doubling the length of the line doubles the coefficient with it.", "The temperature the fluid reaches once the line has run its full length against the seabed."]'::jsonb, 1, 'U is a property of the pipe and its surroundings and of nothing else, which is why the published pipe returns 105.9799311355 Btu/(hr ft2 degF) bare whatever is flowing in it.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 2, 'Two inches of syntactic polypropylene foam and then a 4.0 ft trench are added to the published pipe in that order. What are the three U ratios that describes?', '["79.39290539 for the foam and 79.39290539 again for the trench, because each added build divides the coefficient of the one before it by the same factor.", "1.87167561 for the foam and 79.39290539 for the trench, since four feet of wet soil at k 1.2 is a far heavier resistance than two inches of a foam at k 0.09.", "79.39290539 for the foam, a further 1.87167561 for the trench, and 148.59776436 end to end.", "148.59776436 for each of the two steps taken on its own."]'::jsonb, 2, 'The foam is added to a bare total of 0.0059426060 and the trench to an insulated total of 0.4718007538, so the second addition has far less left to do.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 3, 'Why is a buried coefficient of 0.7132000377 Btu/(hr ft2 degF) not by itself an answer to a hydrate question?', '["It is one of four numbers an arrival needs, and the boundary it would be judged against was never computed anywhere in this module.", "It is quoted on the wrong build, because a hydrate question is asked of the insulated pipe at 1.3348791131 Btu/(hr ft2 degF) rather than the buried one.", "It is quoted to more figures than a field instrument could ever resolve, so the comparison against a laboratory boundary cannot be made at that precision.", "Nothing is wrong with it once the reference diameter is written beside it."]'::jsonb, 0, 'The engine draws no hydrate or wax boundary at all, so the half of the verdict that decides pass or fail is not arithmetic this module performed.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 4, 'Five of the nine functions in the thermal module never see a fluid property. Which four do?', '["The layer resistance, the burial resistance, the overall coefficient, and the pipe mass, since each of them has to know what is flowing before it can pick a film coefficient for the bore.", "The two mass helpers and the two film catalogs, because a density and a film coefficient are both properties of the produced fluid rather than of the pipe.", "The overall coefficient and the three helpers that feed it, which is where the rate first enters the calculation and the reason a U has to be recomputed at every rate.", "The relaxation length, the steady state profile, the inverse for a target arrival, and the cooldown."]'::jsonb, 3, 'Layer resistance, burial resistance, overall U and the two mass helpers are geometry, conductivity and density, so one U describes the line at any rate.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 5, 'What is absent from this module by design rather than by oversight?', '["The film coefficients on the two faces of the pipe, which have to be supplied from a correlation outside the module because no catalog of them ships with it at all.", "Any flow solution: no pressure drop model, no holdup, no phase behaviour, no composition and no hydrate or wax curve.", "The conduction resistance of an individual coating layer.", "The overall coefficient itself, which is assembled by the caller."]'::jsonb, 1, 'It is a heat leak calculator wrapped around a pipe drawing, and the seabed temperature, the soil thickness and the film coefficient all arrive as inputs.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 6, 'The bore side film catalog runs from 300.0000 Btu/(hr ft2 degF) for flowing liquid down to 5.0000 for a shut in and stagnant bore. What does that ratio of 60.000000 mean for a line in service?', '["The inside film is the dominant term at both ends of the range, so it is always the first entry to attack when a stack has to be improved on a flowing line.", "The catalog is describing the same boundary layer at two different seabed temperatures, so the entry to choose follows the ambient rather than the operating state of the line.", "While the line flows the inside film is very nearly a short circuit, and it becomes a term worth arguing about only once the bore goes stagnant.", "A flowing line is harder to insulate than a shut in one."]'::jsonb, 2, 'The bore side entry to choose follows the operating state of the line, and a term that is nearly a short circuit at 300.0000 Btu/(hr ft2 degF) is one worth arguing about at 5.0000.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 7, 'The module ships a seabed with current at 200.0000 Btu/(hr ft2 degF) as an outside film. What kind of number is that?', '["A shipped default that somebody chose, exposed as an input precisely because it is one of the uncertain entries in a stack.", "A measured coefficient for a seabed, cut by the same independent oracle in SI that published the golden coefficients this course is validated against.", "A derived quantity the module computes from the ambient temperature and the pipe outside diameter each time an overall coefficient is assembled.", "A hard constant that a caller cannot override."]'::jsonb, 0, 'Quoting it as though the engine measured it puts a guess at the centre of a stack, while on the bare pipe the two films carry 42.39197245 percent and 48.51081376 percent between them.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 8, 'The overall coefficient is asked for a pipe with no layers at all. What comes back?', '["A coefficient built from the two films alone, since a bore side film and an outside film are enough boundary to define a heat leak per square foot of a named area.", "A NaN with no message attached, because the return of the overall coefficient is a bare number and has nowhere to put an error string.", "A coefficient with an empty resistances array and a note saying the wall term was assumed.", "A refusal, ok false, with the message that a pipe needs at least one layer, its own wall."]'::jsonb, 3, 'The films alone are not a pipe, and this is one of the good refusals: the call fails, the message names what is missing, and nothing plausible comes back.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 9, 'One layer is entered with an outside diameter smaller than its inside. Another carries a conductivity id the catalog does not hold. How does the stack treat that pair?', '["It returns a layer resistance of zero for both, leaving the terms in the stack and the shares still summing to 100.00000000 percent.", "It refuses both, ok false, with the identical message that every layer needs an inside diameter, a larger outside diameter and a positive conductivity, because the two are one input class.", "It refuses the inverted diameters and falls back to carbon steel on the unknown id.", "It returns a bare NaN for both, having no field for a message."]'::jsonb, 1, 'Both are refused by name, and that is what makes them the good refusals: the call fails and nothing plausible comes back.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 10, 'The relaxation length is handed a zero heat transfer coefficient. Why is what comes back more dangerous in a spreadsheet than the refusal a bad pipe earns?', '["It is a zero rather than a NaN, and a zero relaxation length reads as a line that has already reached ambient, which is a plausible answer to the wrong question.", "It is refused with ok false, and a refusal that arrives inside a column of otherwise valid results is the failure most likely to be scrolled past unread.", "It is a bare NaN rather than a result object, so there is no flag to test and no message to read, and a caller who does not check carries it everywhere downstream.", "It returns the previous call''s value."]'::jsonb, 2, 'A NaN is honest and silent, and the two mass helpers behave the same way, returning a bare NaN for an impossible annulus or a zero density.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 11, 'The inverse for a target arrival refuses a target of 40.00 degF on a fluid entering at 180.0 degF against a 40.0 degF ambient, and it also refuses a target of 185.00 degF. Why are those two refusals written as different sentences?', '["One is a genuine refusal while the other is a warning attached to a returned coefficient, so the caller has an answer in the second case and none in the first.", "They are two readings of the same failure, and the module writes them differently only because the target sits on opposite sides of the inlet temperature rather than for any reason in the physics.", "The first is refused on the ambient and the second is refused because 185.00 degF is above the practical ceiling the module carries for an inlet temperature on any line.", "One is a physical impossibility and the other is a question about the wrong thing."]'::jsonb, 3, 'A line cannot arrive above the ambient it is losing heat to, and a fluid that already enters below the target has a problem insulation cannot fix.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 12, 'A profile is run with an inlet 20.0 degF below the 40.0 degF ambient. The engine returns ok true and an arrival of 39.5203295082 degF. Is that a defect?', '["No. A cold line warms towards its surroundings on the same exponential, and this is the one direction of the balance that needs no special case at all.", "Yes, because a line below ambient is outside the range the shape factor and the two film catalogs were built for, and the module should have refused it.", "Yes, because the arrival is quoted below the ambient it is approaching, which is the same impossibility the inverse for a target arrival refuses.", "No, but only because the length happened to be short."]'::jsonb, 0, 'The arrival of 39.5203295082 degF sits just under the 40.0 degF ambient it is climbing towards, which is exactly what the exponential should produce.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 13, 'TEACHING LINE AKASO SPUR carries a hydrate boundary of 71.00 degF while it flows and 78.00 degF once the line packs up after a shutdown. Where did those two numbers come from?', '["From the thermal module, which draws the boundary from the seabed temperature of 45.00 degF and the inlet of 195.00 degF once the pressures on the line are supplied to it.", "From a laboratory. Neither engine computes where the hydrate boundary is, and both module headers say so.", "From the inhibition module, which computes a boundary and then reports how far a design sits from it.", "From the golden case file, where a boundary is published for each of the three builds of the pipe."]'::jsonb, 1, 'Both numbers describe one fluid and differ because the pressure differs, and TEACHING LINE AKASO SPUR is a construct this course invented rather than a published case.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 14, 'A report quotes a margin of 18.3160299527 degF outside the hydrate region on TEACHING LINE AKASO SPUR. What has to be quoted beside it?', '["The number of stations the profile was returned on, because a margin read off a coarse station table is a margin read between two points the engine interpolated across rather than computed at.", "The relative difference between the golden route and the engine route, which is the accuracy the margin inherits from the two computational paths that produced it.", "The boundary it was measured from, since a margin is a subtraction and the number subtracted is a laboratory value.", "The mass rate, because a margin is linear in it."]'::jsonb, 2, 'The same arrival clears the 71.00 degF flowing boundary by more than it clears the 78.00 degF packed one, on identical thermal arithmetic, because the finish line moved.'),
  ('flowassurance', 'beginner', 'module', 'm01-a-line-that-cools', 15, 'What does ok true actually assert about a call in this module?', '["That the pipe described in the call is the pipe the caller meant to describe, since every field a caller can supply is checked against the geometry before a coefficient is returned.", "That the returned coefficient agrees with the independent oracle to within the round trip separating the two computational routes, which on these builds is a few parts in a hundred million.", "That every term the caller asked for is present in the resistances array, which is what makes counting the entries unnecessary.", "That nothing in the guarded list was hit."]'::jsonb, 3, 'The guarded list is shorter than the list of ways a pipe can be described wrongly, and a hydrate boundary the engine never drew is not on it at all.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 1, 'Strip the published pipe to its steel wall and the stack has three entries. What does that stack say about where a bare subsea pipe keeps its thermal resistance?', '["Almost all of it sits in two thin layers of fluid clinging to its faces, the films carrying 42.39197245 percent and 48.51081376 percent, against 9.09721378 percent in the steel.", "In the steel, which is the thickest solid anything has to cross on the route out.", "Evenly across the three, since a series stack shares a total among its terms.", "In the inside film, because the bore side face is the hotter of the two."]'::jsonb, 0, 'The total is 0.0059426060 hr ft degF/Btu per foot, and swapping steel grades changes nothing at all in that table.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 2, 'Why do the terms in a flowline stack add rather than average?', '["Because the module sums them as an approximation, and a proper parallel treatment would be more accurate but is not offered anywhere in the module.", "Because each term is expressed per foot of pipe, and quantities carrying the same length dimension are always summed rather than combined any other way.", "There is one route out, and a joule leaving the fluid crosses every obstacle on it, which is what puts them in series.", "Because the shares are required to reach 100.00000000 percent."]'::jsonb, 2, 'One large term is then enough to control the answer, which is why the foam at 0.4665266247 runs the insulated build on its own.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 3, 'What does the layer resistance helper take, and what does it return?', '["An inside diameter, an outside diameter, a conductivity and the film coefficient on the face outside the layer, so that the boundary layer riding on the new surface is carried along with the layer that created it.", "A wall thickness and a conductivity, returning a resistance per square foot of surface, which is why a thicker layer of the same material always returns a proportionally larger number than a thinner one.", "A diameter ratio, a conductivity and the temperature difference across the layer, since a conduction resistance is defined against the driving temperature it happens to be measured at.", "An inside diameter, an outside diameter and a conductivity, returning ln(Do/Di) over 2 pi k in hr ft degF/Btu per foot."]'::jsonb, 3, 'No fluid, no rate, no temperature and no clock enters it, which is why the steel wall reads 0.000540611570 on every build of this pipe.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 4, 'The foam layer resistance is 862.960859 times the steel wall resistance on the published pipe. Which of the two ratios inside that product does the geometry account for?', '["The larger one, 288.88888889, because a layer running from 6.625 in out to 8.625 in has to be crossed over far more thickness of material than a wall running from 6.065 in to 6.625 in does.", "The smaller one, 2.98717220, out of log terms of 0.0883158295 against 0.2638145910, while the conductivity ratio of 288.88888889 accounts for nearly all of the product.", "Neither. The product is the ratio of the two shares, 98.88212788 percent against 0.11458472 percent.", "Both equally, since a layer resistance is a log divided by a conductivity."]'::jsonb, 1, 'A layer resistance is ln(Do/Di) over 2 pi k, and the steel has both the thinnest log and the largest k in the drawing.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 5, 'A conductivity id outside the catalog, one written as aerogelBlanket for example, comes back as a NaN with no fallback anywhere. Why is that the right behaviour?', '["Because a NaN is what the module returns for any unrecognised input at all, and consistency across the API matters more than the size of any one error.", "Because the catalog holds defaults, so no entry in it can be the right conductivity for a real coating and none of them should ever be reached for.", "Carbon steel and aerogel differ by 2166.666667, so a silent fallback to the first catalog entry would return a layer resistance smaller by that factor with nothing in the return to question.", "Because a fallback would break the shares, which have to sum to 100.00000000 percent."]'::jsonb, 2, 'A NaN can propagate into a refusal and a plausible wrong number cannot, which is the discipline the conductivity helper header states.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 6, 'The published pipe is expressed bare, then insulated, then buried. What happens to the terms that were already in the stack each time?', '["Nothing is recomputed except the outside film, and the totals of 0.0059426060, 0.4718007538 and 0.8830579621 are one sum extended twice.", "Every term is rescaled onto the new outer surface each time a layer is added, because a resistance referred to one diameter has to be carried onto the next one, which is why the shares move between builds.", "All three totals are independent calculations that happen to share a bore.", "The films are dropped once a coating or a trench is present."]'::jsonb, 0, 'The foam adds its 0.4665266247 to the bare total and the trench adds 0.4112572083 to the insulated one, and the count runs 3, 4 and 5 terms.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 7, 'The inside film holds at 0.0025191879 across all three builds while the outside film moves from 0.0028828065 to 0.0022143296 once the foam is on. What moved it?', '["The seabed current runs faster over a larger coated diameter, so the catalog entry for a swept seabed rises above 200.0000 Btu/(hr ft2 degF) once the coating is on and the film term falls with it.", "The outside face is now the 8.625 in coated diameter rather than the 6.625 in steel, and a film resistance carries an area.", "The foam took over part of the heat the outside film was carrying, so that term now has less to do.", "The inside film is computed on the bore and the outside film on the total resistance."]'::jsonb, 1, 'The bore did not move, so the inside film did not either, and the steel wall reads 0.000540611570 on every build.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 8, 'The foam at 0.4665266247 and the trench at 0.4112572083 hr ft degF/Btu per foot are close in size. Why does one divide the coefficient by 79.39290539 and the other by only 1.87167561?', '["The foam is a conduction layer while the trench is a shape factor, and a shape factor is a weaker kind of resistance that never delivers the reduction its own magnitude appears to promise.", "The trench sits outside the coating, and a resistance placed further from the bore is worth less because it acts on a larger surface than the one the coefficient is referred to.", "The two are not close in size at all once each of them is expressed against its own reference diameter, and that restatement is where the whole difference between the two factors comes from.", "The foam was added to a total of 0.0059426060 and the trench to a total of 0.4718007538."]'::jsonb, 3, 'The first large resistance in a series stack is worth an order of magnitude and the second of the same size is worth less than a factor of two.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 9, 'An engineer prices a trench by subtracting the buried coefficient from the insulated one and reports that burial was almost free. What went wrong?', '["Nothing went wrong with the arithmetic, but the difference should have been taken on the coated outside diameter reference, where the same subtraction returns a larger and more defensible number.", "The subtraction was made between two builds that do not share a bore, so the two coefficients are referred to different areas and cannot be differenced at all without a conversion between them.", "Coefficients do not add and do not average. The resistances add, and a coefficient is what comes out of inverting the sum.", "Burial really is almost free at this depth."]'::jsonb, 2, 'The ground term that trench added is 46.57193819 percent of the finished stack, which no difference of coefficients will ever show.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 10, 'Besides the coefficient itself, what comes back from the overall coefficient call?', '["A flag, the total resistance in hr ft degF/Btu per foot, a referenceIdIn naming the diameter the coefficient is expressed against, and an array of terms each carrying a resistance and a share.", "A coefficient, a total resistance and a relaxation length, so one call gives both the pipe and the distance scale.", "A coefficient and a note naming the term that dominates, so the array need not be read at all.", "A coefficient and the ambient temperature it was built against."]'::jsonb, 0, 'On the published insulated build that is 1.3348791131, total resistance 0.4718007538, referenceIdIn 6.065 in, and 4 terms.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 11, 'How is the coefficient built out of the total resistance?', '["It is one divided by the total resistance alone, since a resistance per foot of pipe and a coefficient per square foot of surface are already in the same units and need no area placed between them.", "It is one divided by the product of the total resistance, pi, and the reference diameter in ft.", "It is the total resistance multiplied by the reference diameter in ft and then by pi, which is why a larger reference always returns a larger coefficient.", "It is the sum of the reciprocals of the individual terms."]'::jsonb, 1, 'The total and the coefficient are never two independent readings of a pipe: the coefficient is the total, divided by an area and turned upside down.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 12, 'The golden and the engine agree on the insulated coefficient to 3.079607e-8. What has that agreement established?', '["That the coefficient is accurate to eight figures, since two independent implementations reaching one number to that precision is the strongest evidence of accuracy available anywhere in this course.", "That the film coefficients on both routes have been validated to that precision, because a residual that small could not survive unless every input underneath it were correct to at least as many figures.", "That the conversion factor of 1.7307346000 is exact, since a rounded factor would have shown as a much larger residual in the coefficient column than the one actually reported there.", "That two routes did the same arithmetic on inputs they share."]'::jsonb, 3, 'Both routes inherit the same films, and the oracle carries the unit factor as 1.7307346000 against an exact 1.7307346664, a relative difference of 3.834868e-8.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 13, 'The published buried build reads 0.713200037662 Btu/(hr ft2 degF) at the 6.065 in bore and 0.501513997498 at the 8.625 in coated outside diameter. What about the pipe changed between those two rows?', '["The outside film was recomputed on the larger face, which is the only term in the stack carrying an area and therefore the only one able to move when the reference is changed.", "The trench term was dropped from the second row, because a ground resistance is defined against a coated outside diameter and cannot be referred back to a bore.", "Nothing. The total resistance is 0.883057962117 in both, and only the area the coefficient is expressed against moved.", "The build was rerun with the still water outside film."]'::jsonb, 2, 'The ratio of the two coefficients is 1.4220939819 and the ratio of the two reference diameters is 1.4220939819, agreeing to 4.4409e-16.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 14, 'Which quantity is the same on either reference for the published buried build, and what is it worth?', '["The coefficient multiplied by its own reference diameter, 0.360463185702 Btu/(hr ft degF) per foot of pipe, and pi times that product is one over the total resistance.", "The coefficient itself, at 0.360463185702, once each of the two readings is divided by its own reference diameter in ft rather than multiplied by it, which is the step that takes the area back out of a coefficient.", "The same product, 0.360463185702, which on its own is one over the total resistance.", "The share carried by the dominant term, 52.83080440 percent on either reading."]'::jsonb, 0, 'That product is the conductance per foot of pipe, and a conductance per foot does not care what area you name.'),
  ('flowassurance', 'beginner', 'module', 'm02-resistances-in-series', 15, 'The overall coefficient reports referenceIdIn. What do the three functions in this module that consume a coefficient do with that field?', '["Each reads it and rescales the coefficient onto whichever diameter it was handed, which is why a mismatched pair still returns the right relaxation length and the right arrival temperature.", "Nothing. Each takes a bare diameter, none accepts the overall coefficient result, and keeping the pair together is the caller''s job.", "Each refuses a coefficient whose referenceIdIn does not match the diameter beside it, and names the mismatch.", "Each carries it into its own returned object so a later reader can audit the reference."]'::jsonb, 1, 'A coefficient computed on the coated outside diameter and handed over with the bore raises no error and puts the relaxation length out by 42.209398 percent.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 1, 'The foam ends up carrying 98.88212788 percent of the insulated build. What is that share a claim about?', '["Everything else being small: the coating is not competing with the rest of the stack, it is many times the whole of it, at 0.4665266247 against a bare total of 0.0059426060.", "The material, which at k 0.0900 is the best insulator the catalog offers.", "The thickness, since 2.0 in is enough wall to dominate any stack it is placed in.", "The reference diameter the build happens to be expressed against."]'::jsonb, 0, 'The insulated total comes to 0.4718007538 hr ft degF/Btu per foot, almost all of it in the one added term.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 2, 'What happened to the inside film and the steel wall when the foam went on?', '["Both resistances fell, because the foam intercepts heat before it reaches either of them and a term that carries less heat contributes less resistance to the stack it sits in.", "Both resistances rose, because the coated pipe presents a larger outside surface and every term in a stack is rescaled onto the outermost face each time a layer is added to it.", "Their resistances did not move at all. Their shares fell, the inside film from 42.39197245 percent to 0.53395165 percent and the steel from 9.09721378 percent to 0.11458472 percent.", "The steel wall was dropped from the array once a coating was present."]'::jsonb, 2, 'The inside film reads 0.0025191879 and the steel 0.000540611570 on both builds, and only the denominator underneath their shares changed.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 3, 'The outside film did move when the foam went on, from 0.0028828065 to 0.0022143296. Why is that a different kind of change?', '["It is a change of catalog value, because the seabed with current entry of 200.0000 Btu/(hr ft2 degF) applies to bare steel and the still water entry of 50.0000 applies once a coating is in place.", "It is a change of area. The outside face is now the 8.625 in coated diameter rather than the 6.625 in steel, and a film resistance carries an area.", "It is a change of share only, since the two films are the terms whose shares are recomputed against the new total while their resistances are held.", "It is a rounding difference between the two builds."]'::jsonb, 1, 'The bore is untouched by a coating, so the inside film holds at 0.0025191879 while the outside one falls onto a larger face.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 4, 'Aerogel at k 0.0120 gives a layer resistance exactly 7.50000000 times that of syntactic polypropylene at the same 2.0 in. The two coefficients differ by 7.42733831. Why is the second number smaller?', '["Because a layer resistance is inverse in conductivity while a coefficient is inverse in the square of it, so the two ratios can never be equal on any pipe or in any material.", "Because the aerogel build is expressed against a different reference diameter, and the difference between 7.50000000 and 7.42733831 is exactly the ratio of the two references the two builds carry.", "Because the shares of the two builds differ, at 99.849492 percent for the aerogel and 98.882128 percent for the syntactic foam, and a coefficient ratio is the ratio of the two shares.", "The films and the steel wall are still in the stack and did not move."]'::jsonb, 3, 'The layer resistance is exactly inverse in k, at 3.4989496854 against 0.4665266247, but U also carries terms the material never touched.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 5, 'Two inches of concrete weight coat at k 0.9000 on the published pipe leaves the coefficient at 12.1285554677 Btu/(hr ft2 degF). What is the lesson in that row?', '["That a weight coat has to be entered as a burial term rather than as a layer, because concrete in contact with the seabed conducts through the soil around it as well as through itself.", "That the published films are too optimistic for a heavy coating, and a still water entry of 50.0000 Btu/(hr ft2 degF) would be the honest choice on a concrete surface.", "Thickness is not insulation. A coating of the same 2.0 in in a material an order of magnitude more conductive than the foam leaves a coefficient an order of magnitude worse.", "That the concrete row is a published case and the other four are sweeps."]'::jsonb, 2, 'The concrete layer resistance is 0.0466526625 against 0.4665266247 for the same thickness of syntactic foam.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 6, 'One 2.0 in foam layer carries 98.88212788 percent of one build and 52.83080440 percent of another, and its resistance is 0.4665266247 in both. What does that spread of 46.05132348 percentage points describe?', '["The builds, not the foam. A share is a division, and the denominator is whatever else was entered into the stack alongside it.", "The uncertainty in the foam conductivity, since the same layer entered at the ends of a plausible range for k 0.0900 produces shares that far apart.", "The difference between a published case and a derived sweep point.", "The effect of the reference diameter on the share column."]'::jsonb, 0, 'Adding the trench puts 0.4112572083 into the same total, taking 46.57193819 percent of the finished stack, and the foam share falls to make room for it.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 7, 'The published pipe is shut in and the bore side film is taken to the stagnant catalog value of 5.0000 Btu/(hr ft2 degF). What happens?', '["The inside film resistance rises to 0.1259593944 and the coefficient rises with it to 1.3163448815, because a stagnant bore holds its heat and a line holding heat leaks less of it per square foot of surface.", "The inside film resistance rises to 0.1259593944, that term takes 21.16107640 percent of the stack, and the coefficient falls to 1.0580538200.", "The foam share rises, because the term that lost resistance was the one competing with it.", "Nothing moves, because the overall coefficient never sees an operating state."]'::jsonb, 1, 'The flowing liquid entry beside it is 60.000000 times larger, so the pipe did not change and the condition did.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 8, 'Putting the published insulated pipe in still water rather than a swept seabed takes the outside film to 0.0088573186. How much is that worth?', '["46.57193819 percent of the stack, because the outside film and the ground term occupy the same position outside the coating and are therefore worth the same to any build.", "Nothing measurable, because the outside film catalog entry of 50.0000 Btu/(hr ft2 degF) is a default and defaults are not carried into the resistance array at all.", "1.85127692 percent of the stack, taking the coefficient from 1.3348791131 to 1.3163448815 Btu/(hr ft2 degF).", "A factor of four, following the ratio of the two catalog entries."]'::jsonb, 2, 'The foam still carries 97.50919137 percent, which is why a fourfold change in one catalog entry moves the coefficient so little.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 9, 'A stack is built and one coating the caller meant to enter is missing from the layer list. What does the share column look like?', '["It carries a term with a resistance of zero and a share of zero, which is the entry a reader has to look for whenever a coating is suspected of being absent from the list handed in.", "It fails to sum to 100.00000000 percent, and the shortfall is the share the missing coating would have carried had it been entered into the stack in the first place.", "It is returned with ok false, because the module compares the layer count against the number of diameters the caller supplied and refuses a list that does not close.", "Exactly as convincing as it does when everything is there, and it still sums to 100.00000000 percent."]'::jsonb, 3, 'The shares are recomputed on every call and they sum over the terms that were entered, so a share will never tell you whether the build is the one you meant.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 10, 'The first quarter inch of foam wall on the published pipe divides the coefficient by 22.61753379, while two inches added out at 12.625 in divides it by 1.42480183. Where does that difference come from?', '["A layer resistance goes as ln(Do/Di), so a logarithm cares about the ratio of the diameters rather than the thickness, and equal thickness added far out is less log.", "The conductivity of the foam falls as the wall gets thicker.", "The outside film grows on a larger face and cancels the gain.", "The published build sits between the two steps and is not comparable to either."]'::jsonb, 0, 'The first quarter inch is ln(7.125 / 6.625) at 0.0727593543 and a quarter inch added at the surface is ln(16.625 / 16.125) at 0.0305367239, a ratio of 2.38268370.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 11, 'In the foam sweep the ratio column falls to 1.28791107 at the published build and then reads 1.41068230 on the next row. Has foam started paying again?', '["Yes. Past a certain wall the foam begins to dominate the stack completely, and once the films and the steel are irrelevant every further inch acts on the layer resistance alone and buys more than the inch before it did.", "No. The rows widened, from 0.2500 in steps to 0.5000 in, so that row was bought with twice the wall.", "Yes, because the outside film falls on a larger coated diameter and that gain is added to the layer gain.", "No, because the ratio column is not a ratio between rows at all."]'::jsonb, 1, 'Read the wall column alongside the ratio column and the pattern is intact: 1.42480183 at the last row was bought with 2.0000 in more of wall.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 12, 'The foam share climbs from 95.729166 percent at a quarter inch of wall to 99.741999 percent at five inches. What does the top of that column tell a designer?', '["That the sweep has found the thickness at which the coating starts to pay for itself, since a share above 99.421867 percent is the conventional point at which an insulation design is regarded as complete on a subsea line.", "That the reference diameter has drifted with the coating, so the shares in the last rows of the sweep are being computed against a larger area than the ones in the first rows were.", "That the films are being underestimated at the larger diameters, because the outside film catalog entry was chosen for the bare steel face and never revisited as the coated diameter grew.", "That the rest of the stack has already been made irrelevant, so there is nothing left for more foam to remove."]'::jsonb, 3, 'At a 5.0000 in wall the coefficient is 0.3860878878 and the only term left to improve is the one already being improved.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 13, 'Where in the foam sweep does the engine put the optimum thickness?', '["At the 8.625 in row, which is why that row is the published build and the one the golden cases were cut on rather than any of the sweep points around it.", "At the row where the marginal ratio first falls below 1.28791107, which is the point past which each further inch of wall returns less than the inch before it did.", "Nowhere. The sweep contains no optimum and the module offers none, because it prices no material.", "At the row where the foam share first passes 99.421867 percent."]'::jsonb, 2, 'Where a coating stops being worth its cost is a question about money and installation, and the overall coefficient returns a number for a foam wall of any size typed into it.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 14, 'A line is insulated until the coefficient reaches 0.3860878878 Btu/(hr ft2 degF). What can still not be said about it?', '["What its overall coefficient is referred to, because the reference diameter drifts with the coating and the module stops reporting a referenceIdIn once the layer list runs past two entries in length.", "Whether anything is safe, because neither engine computes a hydrate boundary and every margin is conditional on a laboratory number somebody else supplied.", "What its layer resistance is, since the sweep reports coefficients rather than terms.", "How many terms the stack holds."]'::jsonb, 1, 'It produces a temperature and not a verdict, and the thermal module header says the boundary comes from a lab or a compositional flash and is supplied by the consumer.'),
  ('flowassurance', 'beginner', 'module', 'm03-insulation', 15, 'A coating layer is entered with an id the catalog does not hold and the call comes back with a NaN for that conductivity. What did that NaN prevent?', '["A layer resistance smaller by 2166.666667, which is what a silent fallback to the first catalog entry would have handed back with ok unchanged and nothing in the return to question.", "A layer entered at the wrong thickness, which is the other way an insulation entry goes wrong.", "A coefficient referred to the wrong diameter, which no other guard in the module catches.", "A share column that does not sum to 100.00000000 percent."]'::jsonb, 0, 'Carbon steel to aerogel is 2166.666667, and a NaN can propagate into a refusal while a plausible wrong number cannot.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 1, 'How does the module treat the soil around a buried line?', '["As a boundary condition, replacing the outside film with a soil temperature held at the ambient value and applied directly to the coated surface of the pipe without any resistance between them.", "As one more term in the same series stack, sitting outside the last coating and added the way a layer is added.", "As a correction applied to the finished coefficient after the layers and the films have been stacked and inverted, which is why it is reported outside the resistances array.", "As a second outside film, whose coefficient is read from the soil catalog."]'::jsonb, 1, 'The published buried build returns 5 terms, a total of 0.8830579621 hr ft degF/Btu per foot and a coefficient of 0.7132000377.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 2, 'Four feet of wet soil is added to the published insulated pipe. What is that worth against what the foam was worth?', '["A factor of 79.39290539 again, since the ground resistance of 0.4112572083 is close in size to the foam resistance of 0.4665266247 and equal additions to a series stack buy equal factors.", "A factor of 148.59776436, which is the whole of the improvement from the bare pipe and belongs to the trench because the trench is the outermost term in the finished stack.", "Nothing at all, because a trench changes where the heat goes rather than how much of it leaves, and a shape factor cannot alter a coefficient built from layers and films.", "A factor of 1.87167561 against the foam''s 79.39290539."]'::jsonb, 3, 'Once one term dominates a stack the next one added has little left to do, and bare to buried is 148.59776436 in all.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 3, 'TEACHING LINE AKASO SPUR is buried 3.00 ft to centreline in wet soil at k 1.20 under a 16.750 in coated outside diameter. Its trench resistance reads 0.2835082263 with the foam in place and 0.2835082263 with the foam removed, at shares of 32.148093 percent and 77.505874 percent. What moved?', '["The denominator. Nothing about the soil, the depth or the coated diameter changed between the two builds.", "The shape factor, because removing a layer changes the coated diameter the acosh argument is built on.", "The soil conductivity, which the module rereads from the catalog on every call.", "Both the resistance and the share, since a share is a property of a term."]'::jsonb, 0, 'A share belongs to a build, so a burial share quoted from one line says nothing about a line with different insulation on it.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 4, 'The published 4.0 ft trench is run at soil k 0.5000 and again at k 2.0000. The ground resistance moves from 0.9870172999 to 0.2467543250 while the coefficient moves from 0.4317172866 to 0.8764769611. Why is the second ratio smaller?', '["The shape factor moves with the conductivity as well, so part of the change in the resistance is geometry rather than material and does not carry through to the coefficient at all.", "The coefficient is referred to the 6.065 in bore while the ground resistance is defined on the 8.625 in coated diameter, and the ratio between the two references separates the two columns.", "The ground term is exactly inverse in k, but the films, the steel and the foam sit in the same stack and none of them cares about the soil.", "The two soils are catalog defaults and the coefficients were computed on measured values."]'::jsonb, 2, 'The ground share runs from 67.658698 percent at k 0.5000 down to 34.340349 percent at k 2.0000, so what is left of the stack matters more at the wetter end.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 5, 'A line is designed on dry soil at k 0.5000 and buried in wet seabed at k 1.2000. What does the module say about that?', '["It refuses the second call, because a coefficient already computed on one soil cannot be recomputed on another without rebuilding the whole stack from the layer list upward.", "Nothing. Both are valid answers to the question each was asked, and nothing in either return complains.", "It flags the second coefficient with a note, since the two catalog soils differ by more than the tolerance the module carries on a ground term.", "It returns a NaN, because two soil ids were supplied for one trench."]'::jsonb, 1, 'The design coefficient is 0.4317172866 and the line as buried is 0.7132000377 Btu/(hr ft2 degF), so it loses heat faster than the design said.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 6, 'What does the soil catalog offer, and what does it not?', '["Two defaults and a warning whenever the k supplied for a trench falls outside the range between them, which is the guard that catches a conductivity typed in the wrong units entirely.", "A full range of seabed materials with a recommended value for each water depth, which is why a site measurement is not needed before a first pass can be run on a line.", "One default for the seabed and a second value for backfill, so that a trench refilled with imported material can be entered as two conductivities rather than one.", "Two defaults, wet soil at 1.2000 and dry soil at 0.5000 Btu/(hr ft degF), and no authority: every trench still takes its own k."]'::jsonb, 3, 'An id the catalog does not recognise returns a NaN, which is deliberate: an earlier version returned carbon steel for an unknown id.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 7, 'What is the ground resistance built from?', '["acosh(2H/D) divided by 2 pi k, with H the depth to the centreline of the coated pipe and D the coated outside diameter.", "The depth divided by the soil conductivity and the coated diameter.", "The buried volume of soil above the pipe, divided by its conductivity.", "A shape factor read from the soil catalog against the trench depth."]'::jsonb, 0, 'Two lengths, one conductivity, an inverse hyperbolic cosine, and nothing else at all, which is why 4.0 ft on 8.625 in in wet soil is 0.4112572083.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 8, 'The acosh column runs 1.6825620278 at 1.000000 ft and 3.1008062984 at 4.000000 ft while the ground resistance runs 0.2231567198 and 0.4112572083. What is the division by 2 pi k doing to that column?', '["Inverting it, which is why a deeper trench returns a smaller ground term than a shallow one on the same coated diameter, and why the resistance column falls down the table as the shape factor column climbs.", "Flattening it, because the conductivity of a wet soil rises with depth, so the divisor grows down the column instead of holding at the one value entered for the trench.", "Scaling it, and nothing else. The acosh column carries the whole shape of the answer, and 2 pi k is one fixed divisor applied to every row, which is why the two columns stay in exact proportion.", "Converting it from the SI the shape factor is computed in into the field units it is reported in."]'::jsonb, 2, 'At 4.000000 ft in wet soil at k 1.2 the shape factor 3.1008062984 becomes a resistance of 0.4112572083 hr ft degF/Btu per foot.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 9, 'A pipe lies on the seabed rather than in a trench. Half the published coated diameter is 0.35937500 ft, and there the ground resistance is 0.0000000000. Is that a limitation of the shape factor?', '["Yes. The shape factor is derived for a buried cylinder, so at the surface it falls outside its own range of validity and the zero is the arithmetic breaking down rather than a physical result the module can defend.", "No. A pipe on the bottom has no soil above it to conduct through, and 2H/D is exactly 1.00000000 where acosh vanishes.", "Yes, but only because the published coated diameter is large. On a smaller coated diameter the same geometry returns a small positive resistance rather than a zero.", "No, and the buried build accordingly returns a coefficient lower than the exposed one."]'::jsonb, 1, 'The buried build returns 1.3348791131 Btu/(hr ft2 degF) there, the exposed answer to the last figure, and that is also the check that the shape factor is the right one.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 10, 'At the H equal to D over 2 limit the golden publishes 1.6148921380e-9 K m / W and the engine returns 0.000000000000 hr ft degF/Btu per foot. What is the relationship between those two numbers?', '["Both are floating point residue of an exact zero, and the two residues differ in size because the two arithmetics reach acosh(1) by different routes.", "The first is the answer in SI and the second is the same answer in field units, so one converts into the other with the factor of 1.7307346000 the oracle carries.", "The engine has truncated a small but real ground resistance to zero, and the golden preserves it.", "They disagree, and the disagreement is the tolerance the golden case is accepted within."]'::jsonb, 0, 'The exact answer both are approximating is acosh(1) over 2 pi k, which is 0.000000000000, so neither should be converted into the other.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 11, 'A trench is entered shallower than half the coated diameter. What does the ground resistance helper return, and why?', '["A resistance of zero, on the grounds that a pipe that shallow is effectively lying on the bottom and a zero is the correct physical answer for a line resting on the seabed surface.", "A refusal object carrying ok false and a message naming the trench depth as the field that could not be resolved, which is the same treatment a bad layer receives from the stack above it.", "The resistance at the floor depth of 0.35937500 ft, since the helper clamps any depth below the floor onto it rather than extrapolating a shape factor outside its own valid range.", "A NaN, because 2H/D is then below 1 and acosh has no real value there."]'::jsonb, 3, 'On the published 8.625 in coated diameter, 0.30 ft gives 2H/D of 0.83478261 and no real acosh at all.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 12, 'Somebody reads 0.2231567198 at 1.000000 ft of cover, wants twice that resistance, and specifies twice the depth. What arrives?', '["Twice 0.2231567198, since a conduction shape factor is linear in depth for as long as the coated diameter is held constant, and the trench on this pipe was never widened at any point.", "0.4112572083, which is the published value and the resistance any doubling of a trench depth converges on once the acosh argument is past about two.", "0.3185103955, because acosh moved by only 1.42729466 while the depth doubled.", "A NaN, because the depth is outside the sweep."]'::jsonb, 2, 'Doubling from 10.000000 ft to 20.000000 ft is worth even less, at 1.17253653, since acosh grows like a logarithm once 2H/D is past about two.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 13, 'The published trench is driven from 4.000000 ft to 20.000000 ft. What does that buy?', '["The coefficient goes from 0.7132000377 to 0.5742267291 Btu/(hr ft2 degF) and the trench then carries the whole stack, which is the point past which the coating on the pipe stops mattering to the answer at all.", "The coefficient goes from 0.7132000377 to 0.5742267291 Btu/(hr ft2 degF), and the trench still carries only 56.982867 percent of the stack.", "The ground resistance rises by a factor of five, following the depth.", "Nothing, because the shape factor has already reached its ceiling at 4.000000 ft."]'::jsonb, 1, 'The ground resistance runs from 0.4112572083 to 0.6249732901 over that whole drive, and cover added at 10.000000 ft is the flattest part of the curve.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 14, 'A trench is dug to a top of pipe and reported that way, so 4.0 ft is entered where 4.359375 ft to centreline was meant. What does that cost on the published coated diameter, and where would it cost more?', '["0.4112572083 against 0.4227104126, which is 2.784925 percent, and it costs more on a shallow line where acosh is still steep.", "Nothing, because the module measures depth to the top of pipe.", "The full difference of half a coated diameter, applied to the coefficient.", "More on a deep line, where the argument 2H/D is larger."]'::jsonb, 0, 'At the published depth 2H/D is 11.13043478 and acosh is nearly flat there, so half a foot of confusion buys very little either way.'),
  ('flowassurance', 'beginner', 'module', 'm04-burial', 15, 'The burial term is the shape factor for an isothermal cylinder in a semi-infinite medium. Which of its conditions does the module check?', '["The uniformity of the soil conductivity, which is checked by comparing the k supplied for the trench against the two catalog entries and flagging a value that sits outside both of them.", "The requirement that the surface above the trench sits at the ambient temperature, which is checked against the ambient the profile was given whenever the two calls are made together.", "The requirement that the depth is measured to the centreline, which is checked by comparing the trench depth against half the coated outside diameter and refusing anything below it.", "None of them."]'::jsonb, 3, 'A uniform soil, a flat surface at ambient, no groundwater movement, no seasonal front and a depth to centreline: the function returns a resistance to ten places whether or not any of them holds.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 1, 'The published wall runs 6.065 in to 6.625 in and the mass helper returns 18.9921056882 lbm/ft at a density of 490.0 lbm/ft3, so what arithmetic produced it?', '["An annulus area multiplied by a density and then by the wall thickness of 0.5940 in, which is how a per foot figure is carried from a cross section onto a length of pipe.", "A bore area of 0.2006268247 ft2 subtracted from a coated area, multiplied by the steel density that the module holds in its own constant and reaches for whenever no density is supplied to the call.", "An annulus area of 0.0387593994 ft2 multiplied by one density, and nothing else.", "A published lookup of the mass per foot for that pipe schedule."]'::jsonb, 2, 'The helper is an annulus and one multiplication, and it knows nothing else about the pipe at all.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 2, 'The module ships a steel density constant of 490.0 lbm/ft3, so what does the mass helper do with it?', '["Nothing. The density is an input, and the helper never reaches for the constant on its own.", "It uses it whenever the density argument is left out, which is the reason a call that omits a density still returns a well formed mass rather than the NaN an impossible annulus earns.", "It uses it to check the density supplied, and returns a note whenever the two are far apart, which is the guard against a density entered in the wrong units entirely.", "It uses it for the shell and the supplied density for the contents."]'::jsonb, 0, 'The published cooldown case happens to supply 490.0 lbm/ft3, which is where the published 18.9921056882 lbm/ft comes from.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 3, 'Why is the pipe mass helper not really a steel helper?', '["Because it returns lbm per foot rather than a total weight, so it has no way of knowing whether the shell it was handed is made of steel, of concrete or of a foam, and its name records only what the cooldown slot it feeds normally holds.", "Nothing in its arithmetic mentions steel. Two diameters and a density describe any cylindrical shell.", "Because the module has no catalog of densities, so every material has to be supplied by hand and the name is a leftover from a version that did hold one.", "Because it refuses an annulus whose outside diameter is not the larger of the two."]'::jsonb, 1, 'The same call returns the mass of a foam layer or a weight coat if it is handed those diameters and that density.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 4, 'The published bore at 55.0 lbm/ft3 returns 11.0344753586 lbm/ft. What area is that built on, and why is it that one?', '["The coated area on 8.625 in, because the contents fill everything inside the outermost surface of the line and a coating is part of what holds them in place along its length.", "The annulus between the bore and the steel outside diameter, at 0.0387593994 ft2, since a contents mass and a shell mass have to be built on the same geometry before they can be added into one heat capacity.", "The area the coefficient is referred to, whichever that happens to be, so that the mass and the coefficient stay on the same reference through every step of the calculation.", "The bore area of 0.2006268247 ft2, because a contents mass built on a coated outside diameter would describe a solid rod of oil the width of the whole line."]'::jsonb, 3, 'The 6.065 in bore is also the diameter this pipe''s coefficient is referred to, which is a coincidence of this build and not a rule.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 5, 'On the published pipe the steel mass is 1.72116073 times the contents mass. What does the cooldown header say about that?', '["That the two masses have to be combined into one shell figure before they are handed over, because the cooldown offers one heat capacity slot rather than two separate mass slots.", "That a ratio above one is the test for whether a line is small bore, and that a design on a line failing that test can safely count the fluid alone.", "That leaving the pipe heat capacity out is a common and optimistic error, because on an insulated small bore line the steel can hold as much heat as the oil in it.", "That the steel mass should be scaled by that ratio before use."]'::jsonb, 2, 'A design that counts only the fluid on a line like this has left out the larger of the two masses.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 6, 'TEACHING LINE AKASO SPUR is a gas line on a 9.562 in bore whose contents are at 8.60 lbm/ft3, returning 4.2886768072 lbm/ft against a steel mass of 64.4900327983 lbm/ft. Why does the larger bore carry so much less fluid mass than the published 6.065 in one?', '["The density fell further than the area rose, and a contents mass is one area times one density with nothing else in it.", "The helper reports gas on a standard basis rather than at line conditions, so a gas mass comes back smaller than the fluid actually in the line by the ratio of the two pressures.", "The teaching line is buried, and a buried line is entered at its coated outside diameter rather than at its bore.", "The wall of 0.5940 in takes area away from the bore on the larger pipe."]'::jsonb, 0, 'AKASO SPUR is a TEACHING LINE this course invented rather than a published case, and its contents figure follows from 8.60 lbm/ft3 alone.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 7, 'The published cooldown carries 11.0344753586 lbm/ft of contents at Cp 0.50 and 18.9921056882 lbm/ft of steel at Cp 0.11. What is the total, and who dominates it?', '["7.6063693050 Btu/(ft degF), with the steel carrying the larger share because it is the larger mass, at 1.72116073 times the contents mass on this pipe.", "7.6063693050 Btu/(ft degF), with the contents carrying 72.534444 percent of it.", "The sum of the two masses in lbm/ft, which is the figure a cooldown divides its conductance into.", "5.5172376793 Btu/(ft degF), which is the contents term alone."]'::jsonb, 1, 'The contents heat capacity is 5.5172376793 and the steel 2.0891316257 Btu/(ft degF), so Cp 0.50 against Cp 0.11 is a wider gap than the masses opened.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 8, 'Ordering the two published cooldown terms by mass puts them in one order and ordering them by heat capacity puts them in the other. Which ranking goes into an answer?', '["The mass ranking, since the cooldown divides its conductance into a total mass and applies one blended specific heat to the result rather than carrying two terms separately through the calculation.", "Either, because a ranking is a presentational choice and both orderings describe the same two terms sitting in the same two slots of the same call.", "The mass ranking on a liquid line and the heat capacity ranking on a gas line, since the two specific heats are close enough on a liquid for the masses to decide the order between them.", "The heat capacity ranking, because only the total M Cp goes any further."]'::jsonb, 3, 'The steel is 1.72116073 times the contents by mass and the contents still hold 72.534444 percent of the heat, which is what makes a mass quoted alone worth nothing.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 9, 'The published insulated build gives a conductance per foot of 2.119538792399 Btu/(hr ft degF). Divide the M Cp of 7.6063693050 by it and the units collapse to hours. What is the 3.588690771912 hr that comes out?', '["The no-touch time, which is the hours a shut in line has before it reaches the target temperature it was given, and the figure a cooldown study reports as its answer.", "The relaxation length expressed in time, which is the same quantity the steady state profile uses in distance and which becomes hours once the mass rate is divided out of it.", "A time constant. It does not depend on where the line starts or where it is going, and everything a shutdown asks about is that number multiplied by a log of two temperature differences.", "The time before the masses have to be recomputed on the cooled fluid."]'::jsonb, 2, 'Get the masses wrong and the clock is wrong by exactly the same factor, at every temperature, for the whole event.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 10, 'An insulated line goes into a cooldown. What does the API do about the coating that carries most of its stack?', '["It carries the coating into the shell slot on its own, taking a density from the catalog entry the layer was built with, so that a coated line needs no hand lumping anywhere in the call.", "Nothing at all. There are two mass slots, contents and shell, no helper that lumps a coating into either, and no warning when the layer list is longer than two.", "It offers a third slot for a coating, so a line can be entered exactly as its layer list reads.", "It refuses, because a layer count above the slot count cannot be resolved."]'::jsonb, 1, 'The overall coefficient accepted 2 layers on that build, the cooldown offers 2 mass slots, and the number of them the foam fits into is 0 while it carries 98.882128 percent of the resistance.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 11, 'This course takes syntactic polypropylene foam at 44.0 lbm/ft3 and Cp 0.28 Btu/(lb degF) to weigh the published coating. What kind of numbers are those?', '["TEACHING numbers this course chose, because the engine has no density catalog for insulation and no golden publishes one.", "Engine defaults, held in the same constants block as the steel density of 490.0 lbm/ft3 that the module carries.", "Golden values, cut by the independent oracle alongside the published coefficients.", "Values read from the published cooldown case, which supplies both densities it uses."]'::jsonb, 0, 'On the published pipe from 6.625 in to 8.625 in that is 7.3194745506 lbm/ft and 2.0494528742 Btu/(ft degF), which is 26.943904 percent of the published cooldown M Cp and none of it is in that case.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 12, 'On TEACHING LINE AKASO SPUR the two mass slots hold 68.7787096055 lbm/ft and leave out 112.4591995215 lbm/ft. What do the layers left out carry?', '["Nothing that matters to a cooldown, because a coating outside the steel is on the cold side of the dominant resistance and cannot give its heat back to the fluid before the line has already reached ambient.", "The same fraction of the resistance that they carry of the mass, which is what makes the omission proportional and therefore correctable by scaling the answer up by the ratio of the two masses.", "The share the trench carries, at 32.148093 percent, since the layers outside the steel are the ones the trench conducts through.", "67.414840 percent of the resistance of that line."]'::jsonb, 3, 'Most of the mass and most of the resistance sit outside the API, and AKASO SPUR is a TEACHING LINE rather than a published case.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 13, 'A careful reader fills contents and shell correctly, checks both masses and gets a clean return on an insulated line. What has been silently assumed?', '["That the two slots were entered in the right order, which nothing in the return can confirm because the contents and the shell are summed into one heat capacity before anything is computed from either of them.", "That the coefficient handed to the cooldown was referred to the bore, which is the assumption the API cannot check and the one that moves an answer furthest when it is wrong.", "That everything outside the steel weighs nothing and stores no heat.", "That the specific heats supplied are at line conditions rather than at the stock tank, which is the input neither helper can test against anything it holds."]'::jsonb, 2, 'The two slots are a description of the API rather than a description of the line, and the only route the module allows is lumping a coating into the shell slot by hand.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 14, 'Both mass helpers return a bare NaN when they cannot compute a mass. What does the cooldown do with one?', '["It refuses, because the guard on the total heat capacity fires on any term that is not a finite number and names the slot that could not be resolved in the message it returns.", "It reads its masses as a value or zero, and a NaN is falsy, so a NaN mass arrives as a mass of zero rather than as a failure.", "It substitutes the other slot''s mass, so that a call with one good mass returns the answer for a line made entirely of whatever that slot held.", "It carries the NaN through, so the hours come back as a NaN too."]'::jsonb, 1, 'With both masses NaN the total heat capacity is zero and the call is refused, and with only one bad the term is dropped and the call succeeds.'),
  ('flowassurance', 'beginner', 'module', 'm05-what-the-line-weighs', 15, 'The published cooldown with both masses good gives a no-touch time of 4.6627248553 hr. With only the contents mass NaN it gives 1.2806433091 hr with ok true and no note. Why is that second number harder to spot than noise would be?', '["It is short by 72.534444 percent, which is exactly the contents share of the M Cp, so it is the right answer with one named piece missing rather than a value scattered around the right one.", "It is short by 72.534444 percent, which is a large enough error that a reader will assume the inputs were different rather than that a term was dropped from the sum inside the call.", "It arrives with a time constant and a full station table, and a table that long reads as a completed calculation.", "It is within the tolerance the golden cooldown case is accepted at."]'::jsonb, 0, 'Dropping a term from a sum divides the time constant in the same proportion, and after the masses are summed there is no way to tell how many terms went into the sum.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 1, 'What does an Associate tier stack of resistances contain, and what does it never contain?', '["Geometry, conductivity, two films and the mass rate the line is carrying, because a film coefficient on the bore side is chosen against how fast the fluid is moving past it and therefore against the rate.", "Geometry, conductivity and two films, and no fluid, no rate and no clock appears anywhere in it.", "Geometry, conductivity, two films and the ambient temperature, since a resistance is defined against the temperature difference it is measured across.", "Geometry and conductivity alone, with the films entering only once a fluid is named."]'::jsonb, 1, 'That is why one coefficient describes the line at any rate, and why 105.9799311355, 1.3348791131 and 0.7132000377 Btu/(hr ft2 degF) are properties of three builds rather than of three operating conditions.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which term would you attack first to move the published buried coefficient of 0.7132000377?', '["The inside film, which at 42.39197245 percent is the largest single term in the stack and the one a change of operating condition can move furthest at no capital cost at all.", "The steel wall, since it is the only term whose material can be specified and the only one that carries a structural requirement alongside its thermal one.", "The foam, at 52.83080440 percent, and then the trench at 46.57193819 percent, leaving the films and the steel alone.", "The outside film, by moving the line out of the current into still water."]'::jsonb, 2, 'The share column says which term the answer belongs to, and on that build the two films and the steel together carry the remainder.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 3, 'A layer resistance is a property of one thing and a share is a property of another. Which is which?', '["The resistance belongs to the layer, at 0.4665266247 hr ft degF/Btu per foot for the published foam in every build, and the share belongs to the stack it was put into.", "The resistance belongs to the material, which is why a foam at k 0.0900 returns one figure wherever it is used, and the share belongs to the layer that material was formed into.", "Both belong to the build, since both are recomputed on every call.", "Both belong to the layer, and the two are different expressions of one number."]'::jsonb, 0, 'That foam share reads 98.88212788 percent insulated and 52.83080440 percent buried, a spread of 46.05132348 percentage points across four builds on a layer that never changed.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Why does the steel wall carry only 9.09721378 percent of even the bare published stack?', '["Because the two films sit on either side of it and a term enclosed between two other terms in a series stack always carries less than the terms that bound it do.", "Because it is referred to the bore while the films are referred to their own faces, so its resistance is expressed against a smaller area than either of theirs is.", "Because the bare build is the one build where the shares are computed before the outside film has been placed on the steel outside diameter rather than on the coated one.", "A layer resistance is ln(Do/Di) over k, and the steel has both the thinnest log and the largest k in the drawing."]'::jsonb, 3, 'Its log term is 0.0883158295 against 0.2638145910 for the foam, and its conductivity is 288.88888889 times the foam''s.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 5, 'The published buried build is 0.713200037662 Btu/(hr ft2 degF) at one reference and 0.501513997498 at another, with a total resistance of 0.883057962117 on both. What separates the two coefficients?', '["The area the outside film is placed on, which is the term that moves when the reference changes and the reason the two totals agree while the two coefficients do not agree with each other.", "The ratio of the two reference diameters, 1.4220939819, and nothing else.", "The rounding carried by the two routes, since the golden and the engine reach the buried coefficient by different arithmetic and the residual between them is 3.094143e-8.", "The trench, which is expressed on the coated outside diameter in one reading and on the bore in the other."]'::jsonb, 1, 'The physics did not move: the same layers, the same films and the same trench give one total resistance to the last figure.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What arithmetic check confirms that two coefficients on different references describe one pipe?', '["Multiply each by its own reference diameter in ft. Both give 0.360463185702 Btu/(hr ft degF) per foot, and pi times that product is one over the total resistance.", "Divide each by its own reference diameter in ft, which gives 0.360463185702 on both.", "Multiply each by its own reference diameter in ft, which gives 0.360463185702, and that product on its own is one over the total resistance.", "Multiply the two coefficients together and compare against the total resistance."]'::jsonb, 0, 'That product is the conductance per foot of pipe, and a conductance per foot does not care what area you name.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 7, 'The published wall is 18.9921056882 lbm/ft and the published contents 11.0344753586 lbm/ft. What is the cooldown that consumes them able to hold?', '["Two slots, and the layer list is summed into the shell slot by the module before the call, which is how a coated line is entered without any hand lumping being needed at all.", "As many slots as the overall coefficient accepted layers, so an insulated build hands over three masses and a buried one hands over four.", "Two slots, contents and shell, so the foam carrying 98.882128 percent of the insulated resistance fits into neither.", "One heat capacity, which the caller assembles from as many masses as the line has."]'::jsonb, 2, 'The two mass helpers are geometry and a density, and there is no slot for a coating, no helper that lumps one, and no warning when the layer list is longer than two.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Of everything the Associate tier computes, what decides whether a line is safe?', '["The overall coefficient, once it has been referred to the bore rather than to the coated outside diameter, because that is the reading the three consumers of a coefficient in this module are built to accept.", "The share column, since a build whose dominant term is a coating is insulated against a hydrate risk while a build whose dominant term is a trench is not insulated against it at all.", "The total resistance, which is the one quantity in the stack that does not change with the reference diameter and is therefore the honest measure of a line.", "None of it. Where the hydrate boundary sits is an input, and both engine headers say so."]'::jsonb, 3, 'Every verdict built on any of these numbers is conditional on a laboratory temperature somebody else supplied.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why does the six step reading put the hydrate boundary down before any pipe is entered at all?', '["Because the boundary fixes which of the two reference diameters the rest of the work is carried on, and a stack built on the wrong one cannot be repaired once its coefficient has reached a consumer.", "Because neither engine computes one, so recording the number and its source first is what makes every resistance, share and coefficient computed after it explicitly conditional on a laboratory value.", "Because the module refuses to return a coefficient until a boundary temperature has been supplied to it.", "Because the boundary decides which film coefficients apply."]'::jsonb, 1, 'Taking it first is what stops a stack of resistances from being mistaken for a verdict.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Step three is to build the stack and count the terms. What failure does that count catch that nothing else in the return will?', '["A trench shallower than half the coated diameter, which comes back as the exposed line with ok true and no note, so the entry count is the only check the API offers.", "A layer whose conductivity could not be resolved, which is dropped from the array without a note, so the stack comes back one term short with its shares still summing cleanly.", "A share column that does not sum to 100.00000000 percent.", "A coefficient referred to a diameter the caller did not intend."]'::jsonb, 0, 'On the published 8.625 in coated diameter that floor is 0.35937500 ft, and below it the acosh argument falls under 1 where there is no real value at all.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Step four is to read the shares before reading the coefficient. What does the share column tell you?', '["How accurate the coefficient is, because a share concentrated in one term means the answer rests on one input and inherits the uncertainty of that input alone rather than of the whole stack.", "Which terms were entered, because a term that was left out of the list appears in the array with a share of zero and is therefore visible to a reader who checks the column.", "Which term the answer belongs to, so an argument stays on the dominant term and leaves the small ones alone.", "How much of the coefficient each term contributes, which is why the shares can be differenced to price a change."]'::jsonb, 2, 'On the published buried build the foam is 52.83080440 percent and the trench 46.57193819 percent, and the rest of the stack carries what is left.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 12, 'Step five is to carry the reference diameter with the coefficient. Why can that not be left to the module?', '["Because the module reports referenceIdIn only on a build whose layer list is short enough for the field to be unambiguous, and an insulated or buried build returns it as an empty value that a caller cannot act on.", "The consumers of a coefficient take a bare diameter and cannot see referenceIdIn, so the pairing is the caller''s to keep.", "Because referenceIdIn records the diameter the caller asked for rather than the one the stack was actually built on, so it agrees with the coefficient only when the two happen to coincide.", "Because a coefficient is dimensionally consistent with either diameter."]'::jsonb, 1, 'A coefficient computed on the coated outside diameter and handed over with the bore raises no complaint anywhere and moves a relaxation length by 42.209398 percent.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Two masses are computed and the return is clean. What does the six step reading require on top of that?', '["A recomputation of the coefficient on the same reference the masses were built on, since a mass per foot and a coefficient per square foot have to share a diameter before either can be carried into a cooldown at all.", "A conversion of both masses into one heat capacity before the step closes, because a cooldown accepts one figure and not two.", "A check that the two masses sum to the mass per foot published for that pipe schedule.", "A record of which layers went into which slot, at what density and at what specific heat, and of which layers went nowhere, because a stack of five terms and a mass of two is a fact about the answer."]'::jsonb, 3, 'Lumping a coating into the shell slot by hand is a legitimate route and stops being legitimate the moment it is not written down.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What does ok true assert about a cooldown that was handed one good mass and one NaN?', '["That both masses were resolved, since the guard on the total heat capacity fires on any term that is not a finite number and names the slot that failed in the message it returns.", "That the hours carry a NaN, because a NaN entered into a sum propagates through everything computed from it.", "Only that the call found enough heat capacity to divide by. One good mass out of two is enough for that, and the hours come back short by 72.534444 percent with no note anywhere.", "That the dropped slot was flagged in the station table."]'::jsonb, 2, 'The published case falls from 4.6627248553 hr to 1.2806433091 hr, which is exactly the contents share of the M Cp.'),
  ('flowassurance', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does the Associate tier hand over to the tier after it?', '["Rate, time and temperature: what arrives at the far end, how far along the line the excess is given up, and how many hours a shut in line has.", "The reference diameter, which the next tier resolves.", "The hydrate boundary, which the next tier computes from the arrival.", "The share column, which the next tier prices per foot of trench."]'::jsonb, 0, 'A coefficient says how hard heat leaves per square foot per degF, and it does not say what temperature arrives at the end of the line.'),
  ('flowassurance', 'beginner', 'final', null, 1, 'One published foam layer reads 0.4665266247 hr ft degF/Btu per foot at a share of 97.50919137 percent in still water and at 52.83080440 percent in a 4.0 ft trench. Why does the trench move the share so much further than the still water does?', '["The trench added 0.4112572083 to the total while still water only raised one film to 0.0088573186, so the two changes differ by more than an order of magnitude in the denominator.", "The trench changes the coated diameter the foam resistance is computed on.", "Still water is a derived sweep point and the trench is a published case.", "The trench is outside the coating and the film is inside it."]'::jsonb, 0, 'A share is a division, and the denominator of the buried build is 0.8830579621 against 0.4784437427 for the still water one.'),
  ('flowassurance', 'beginner', 'final', null, 2, 'A coefficient is one over the product of the total resistance, pi and the reference diameter in ft, and a cooldown time constant is a heat capacity divided by that same coefficient times pi times a diameter. What does a wrong reference diameter do across those two?', '["Nothing, because pi and the diameter appear on both sides of the pair and any diameter therefore drops out of a time constant entirely.", "It moves the coefficient and the time constant in the same direction, so the error compounds into a squared factor rather than cancelling anywhere in the chain.", "It cancels only if the same diameter is used in both, and the module never checks that, because no consumer of a coefficient can see referenceIdIn.", "It is caught by the total resistance, which is invariant to the reference and is carried into the cooldown alongside the coefficient it was inverted from."]'::jsonb, 2, 'Mixing an outside diameter coefficient with a bore puts the relaxation length out by 42.209398 percent, which is the reference ratio and nothing else.'),
  ('flowassurance', 'beginner', 'final', null, 3, 'The published foam is 0.4665266247 and the published trench is 0.4112572083 hr ft degF/Btu per foot. Which is worth more to a line that already has the other?', '["The trench, since a ground term stays in place for the life of the line while a coating degrades, and the module prices that difference through the shape factor rather than through the layer resistance.", "Neither, in the sense either would be worth more first. The one added second divides the coefficient by only 1.87167561 while the one added first divided it by 79.39290539.", "The foam, because a conduction layer sits inside the coated surface where the temperature difference driving the heat through it is larger.", "The trench, because it is the outermost term."]'::jsonb, 1, 'The order is what matters and not the material, since the second large resistance in a series stack meets a total that is already large.'),
  ('flowassurance', 'beginner', 'final', null, 4, 'A trench entered at the floor depth returns a ground resistance of 0.0000000000 with ok true, and a layer with an unresolvable conductivity returns ok false. Which of those is a refusal and which is a result?', '["Both are refusals, since a ground resistance of zero is the shape factor declining to answer for a geometry that falls outside the range the method of images was derived on.", "Both are results, since a layer that cannot be resolved is reported as a resistance of zero and left in the array with a share the reader can see.", "The trench is a refusal expressed as a zero, and the layer is a result carrying an error string, which is why one of them arrives with ok true and the other with ok false.", "The layer is a refusal and the trench at the floor is a correct result."]'::jsonb, 3, 'At 2H/D of 1.00000000 the pipe lies on the bottom and has no soil above it, so the buried build returns 1.3348791131 Btu/(hr ft2 degF), the exposed answer to the last figure.'),
  ('flowassurance', 'beginner', 'final', null, 5, 'Two coefficients read 0.713200037662 and 0.501513997498 for one pipe. Which single arithmetic statement proves they describe the same physics, and what does dropping the pi from it cost?', '["Each divided by its own reference diameter gives 0.360463185702, and the pi belongs to the area rather than to the identity.", "Their ratio is 1.4220939819, which is the diameter ratio, and no pi enters that comparison at any point, which is why it is the safer of the two checks to quote.", "Each times its own reference diameter in ft gives 0.360463185702, and pi times that is one over the total resistance. Without the pi the identity simply does not close.", "Their product against the total resistance closes, and the pi cancels."]'::jsonb, 2, 'The invariant is a conductance per foot of pipe, and the total resistance on both readings is 0.883057962117.'),
  ('flowassurance', 'beginner', 'final', null, 6, 'TEACHING LINE AKASO SPUR keeps 32.148093 percent of its resistance in a trench and leaves 112.4591995215 lbm/ft outside its two mass slots. What do those two readings have in common?', '["Both are facts about where the API ends rather than about where the line ends, and neither is reported as a limitation anywhere in a return.", "Both are properties of the soil the line is buried in, since a trench share and the mass a line carries outside its steel are both set by how much backfill was placed over it.", "Both are published golden values for that line.", "Both change when the reference diameter is changed."]'::jsonb, 0, 'AKASO SPUR is a TEACHING LINE, and the layers its mass slots leave out carry 67.414840 percent of its resistance.'),
  ('flowassurance', 'beginner', 'final', null, 7, 'A mass helper handed an impossible annulus returns a bare NaN, while a stack handed an impossible layer returns ok false with a message. Why the difference?', '["The mass helper cannot know whether the annulus was impossible or merely unusual, so it declines to characterise the failure and passes a value that any caller can test in a single comparison against itself.", "The mass helper returns a number and has nowhere to put an error, while the stack returns an object and does.", "The stack is the only function in the module with a guarded list, and the two mass helpers were written before that list existed and have never been brought into line with it.", "A mass is an intermediate and a coefficient is an answer."]'::jsonb, 1, 'A NaN is honest and silent, and a caller who does not check carries it everywhere downstream, which is what a cooldown then reads as a mass of zero.'),
  ('flowassurance', 'beginner', 'final', null, 8, 'The foam carries 98.882128 percent of the resistance of the published insulated build and fits into 0 of the two cooldown mass slots. What does that combination do to a shutdown answer?', '["Nothing, because a coating outside the steel has already given up its heat to the seabed by the time a shutdown begins and cannot return any of it to the fluid inside the line.", "It doubles the answer, since a term absent from the mass and present in the resistance appears in the time constant twice with opposite signs and the two do not cancel.", "It is caught by the guard on the total heat capacity, which fires whenever the layer count handed to the coefficient exceeds the number of masses handed to the cooldown.", "It leaves the heat capacity of the term that dominates the leak out of the clock the leak is divided into."]'::jsonb, 3, 'Taking the foam at 44.0 lbm/ft3 and Cp 0.28 gives 2.0494528742 Btu/(ft degF), which is 26.943904 percent of the published cooldown M Cp and none of it is in that case.'),
  ('flowassurance', 'beginner', 'final', null, 9, 'Aerogel at k 0.0120 takes the published pipe to 0.1797250990 Btu/(hr ft2 degF). What can still not be stated about the line?', '["Its total resistance, since a coefficient built on an aerogel layer is reported without the resistances array that every other build returns.", "Its layer share, because at that conductivity the foam term dominates so completely that the share column saturates and stops distinguishing the remaining terms.", "Whether it is safe, because the temperature it arrives at has to be set against a boundary neither engine computes.", "Its reference diameter, which the module stops reporting once a conductivity falls below the range the catalog covers."]'::jsonb, 2, 'Insulation produces a temperature and not a verdict, and the aerogel layer resistance of 3.4989496854 is 7.50000000 times the syntactic foam one while the coefficients differ by 7.42733831.'),
  ('flowassurance', 'beginner', 'final', null, 10, 'A layer resistance is a log over a conductivity and a ground resistance is a shape factor over a conductivity. Where does the module treat a bad one of each differently?', '["A layer that cannot be resolved is refused with ok false, while a trench that cannot be resolved has its term dropped and the call returns ok true with no note.", "A bad layer is dropped and a bad trench is refused.", "Both are refused, and only the message differs between them.", "Both are dropped, and the term count is the only tell in either case."]'::jsonb, 0, 'The conductivity helper header states that a NaN propagates into a refusal and a plausible wrong number does not, and the trench branch does not follow it.'),
  ('flowassurance', 'beginner', 'final', null, 11, 'A coating datasheet quotes a share of 98.88212788 percent for a 2.0 in foam. What has to be quoted beside it before that figure means anything?', '["The reference diameter the share was expressed against, because a share is a resistance divided by a total and a total carries an area exactly as a coefficient does, so the two references give two shares.", "The build the share was computed on, since the same layer carries 52.83080440 percent once a trench is added.", "The golden case the share came from, so that a reader can separate a published share from a derived sweep point and treat the two with the confidence each deserves.", "The mass rate the build was run at."]'::jsonb, 1, 'A share is a division and the denominator is the build, spreading 46.05132348 percentage points across four builds on a layer that never moved.'),
  ('flowassurance', 'beginner', 'final', null, 12, 'One published pipe has a foam term with almost all of the resistance and a steel term with almost all of the mass. Which of the two ends up in a cooldown?', '["Both, because the coefficient handed to the cooldown already carries the foam resistance and the cooldown reconstructs a coating mass from the layer list it was built on.", "Neither, because a cooldown is run on the contents alone and the shell slot exists for a line that has been pigged dry rather than for one holding fluid.", "The foam, because a cooldown is driven by the term that carries the resistance and the shell slot is filled with whatever layer the share column reports as dominant.", "The steel, in the shell slot, while the foam has nowhere to go."]'::jsonb, 3, 'The published steel mass is 18.9921056882 lbm/ft against 11.0344753586 lbm/ft of contents, and the foam at 7.3194745506 lbm/ft is in neither slot.'),
  ('flowassurance', 'beginner', 'final', null, 13, 'What single fact about this course makes every margin in it conditional?', '["The film coefficients are catalog defaults, so every coefficient inherits a chosen number rather than a measured one and every margin built on it inherits the same choice.", "The golden coefficients were cut in SI and converted at the boundary, so every field unit answer in the course carries a conversion factor that is itself only carried to eight figures.", "The hydrate boundary is an input, computed by neither engine and supplied by a laboratory.", "The published cases set no pressures anywhere."]'::jsonb, 2, 'Both module headers say so, and every hydrate temperature printed anywhere in this course is a teaching input rather than an engine output.'),
  ('flowassurance', 'beginner', 'final', null, 14, 'What does the thermal module refuse to solve?', '["Flow. There is no pressure drop model, no holdup, no phase behaviour and no composition anywhere in it.", "Conduction through a layer whose conductivity is not in the catalog, since the module has no route to a resistance for a material it cannot name and refuses that layer outright.", "A profile on a line entering below its ambient temperature.", "A coefficient on a pipe carrying more than two layers."]'::jsonb, 0, 'It is a heat leak calculator wrapped around a pipe drawing, and it is very good at that one job.'),
  ('flowassurance', 'beginner', 'final', null, 15, 'A line is shut in and the bore goes stagnant. Which catalog entry now matters that did not matter before?', '["The outside film, which is the term that grows on a line no longer carrying heat to it and which the catalog offers at 200.0000 for a swept seabed and 50.0000 for still water.", "The bore side film, which falls from 300.0000 to 5.0000 Btu/(hr ft2 degF), a ratio of 60.000000.", "The soil conductivity, because a shut in line has time for the seasonal front in the seabed above it to reach the trench and change the term the shape factor is divided by.", "The steel conductivity of 26.0000 Btu/(hr ft degF)."]'::jsonb, 1, 'That one term goes from 0.53395165 percent of the published insulated stack to 21.16107640 percent, and the coefficient falls to 1.0580538200.'),
  ('flowassurance', 'beginner', 'final', null, 16, 'The inverse for a target arrival carries two distinct refusal messages. What separates them?', '["One is returned when the target sits below the ambient and the other when it sits above the inlet, and both are the same statement about a target outside the range the exponential can produce between those two temperatures.", "One is a refusal and the other is a warning attached to a coefficient that was returned anyway, so a caller has something to work with in the second case and nothing at all in the first.", "One applies to a liquid line and the other to a gas line, because the two carry different practical ceilings on how much insulation can be specified for them.", "One target is physically unreachable and the other names the wrong problem."]'::jsonb, 3, 'A line cannot arrive above the 40.0 degF ambient it is losing heat to, and a fluid entering below its target has a problem insulation cannot fix.'),
  ('flowassurance', 'beginner', 'final', null, 17, 'A profile is run on a fluid entering 20.0 degF below the ambient and returns 39.5203295082 degF. What has the module done?', '["Clamped an impossible arrival onto the ambient, which is why the answer sits so close to 40.0 degF and why the same call at a longer length returns the same number again.", "Returned a coefficient rather than an arrival, since a line below ambient has no excess to lose and the profile has nothing left to compute for it.", "Warmed the line towards its surroundings on the same exponential, which is the one direction of this balance that needs no special case.", "Refused, and reported the refusal as an arrival."]'::jsonb, 2, 'The arrival sits just under the 40.0 degF ambient it is climbing towards, which is exactly what the exponential should produce.'),
  ('flowassurance', 'beginner', 'final', null, 18, 'One fluid on TEACHING LINE AKASO SPUR carries a hydrate boundary of 71.00 degF flowing and 78.00 degF packed. Why are there two?', '["The pressure differs between the two states, and a hydrate boundary is a fluid property at a pressure rather than a property of the fluid alone.", "The engine computes one for each of the two operating states.", "One is a golden value and the other is a teaching number.", "One is measured on the seabed and the other at the inlet."]'::jsonb, 0, 'Neither number was computed by anything in this course, and the packed one is the harder to meet on a line that has already stopped moving.'),
  ('flowassurance', 'beginner', 'final', null, 19, 'What is the total resistance of the published buried build, and how is it reached?', '["0.8830579621 hr ft degF/Btu per foot, by rebuilding all five terms on the coated outside diameter once a trench is present, which is why the two films differ between the insulated and the buried builds.", "0.4718007538 hr ft degF/Btu per foot, since the ground term is applied to the coefficient after the stack has been inverted rather than being added into the sum of resistances.", "0.4112572083 hr ft degF/Btu per foot, which is the ground term itself and the figure the buried coefficient is built from once the pipe terms have been absorbed into it.", "0.8830579621 hr ft degF/Btu per foot, by adding a ground term to the insulated total."]'::jsonb, 3, 'The trench adds 0.4112572083 to a total of 0.4718007538, and the count runs from 4 terms to 5 terms.'),
  ('flowassurance', 'beginner', 'final', null, 20, 'Which entries in the published stack are the genuinely uncertain ones?', '["The two films, which is exactly why they are exposed as inputs and shipped with catalogs a caller is expected to override.", "The layer conductivities, since a coating datasheet is rarely available at design stage and the shipped catalog carries one value per material for coatings that vary from batch to batch.", "The reference diameter, which the caller chooses.", "The soil conductivity alone, which no other term depends on."]'::jsonb, 0, 'Two routes agreeing to 3.079607e-8 have agreed about arithmetic on inputs they share, and both inherit the same film choices.'),
  ('flowassurance', 'beginner', 'final', null, 21, 'The insulated build reports a total resistance of 0.4718007538 hr ft degF/Btu per foot beside a coefficient of 1.3348791131. What does the total say that the coefficient does not?', '["That the terms were entered in the right order, because a total is the sum of the array in the order the layers were handed in and a list running from the outside inward returns a different total from one running from the bore outward.", "That the stack itself is fixed. A total does not move when the reference moves, while the same build reads 1.334879113149 at the bore and 0.938671515507 at the coated outside diameter.", "That the films were chosen well, since a total resistance is dominated by the two catalog entries a caller has to select by judgement.", "That the build carries 4 terms rather than 3 terms."]'::jsonb, 1, 'The ratio of those two coefficients is 1.4220939819, which is the ratio of the two reference diameters and nothing else.'),
  ('flowassurance', 'beginner', 'final', null, 22, 'The engine reports referenceIdIn and no consumer in the module accepts it. What is the only defence?', '["Building every coefficient on the bore, since the three consumers all take a bore diameter and a coefficient referred to a coated outside diameter is therefore never usable by any of them.", "Writing the reference down beside the number every time, in a table, in a note, in a handover.", "Passing the whole coefficient result object rather than the coefficient itself, which is the route the module documents and the one that keeps the field with the number it belongs to.", "Checking the total resistance, which will disagree if the pair was mixed."]'::jsonb, 1, 'A mixed pair is dimensionally consistent, raises no complaint anywhere, and puts an arrival out by 13.55773419 degF at 26400.0 ft on the published buried build.'),
  ('flowassurance', 'beginner', 'final', null, 23, 'Both film resistances and both layer resistances are per foot of pipe. Which of them changed when the coating went on, and why?', '["Both films, because a coating placed between them changes the temperature at which each of the two boundary layers sits and a film coefficient is evaluated at the surface temperature it clings to.", "The inside film, because the coating changes the ratio of the bore area to the outside area and the bore side term is normalised on that ratio before it enters the stack.", "The steel wall, because its outside face is now in contact with a foam of much lower conductivity rather than with the seawater it was previously losing heat to directly.", "The outside film, because its face moved from 6.625 in to 8.625 in."]'::jsonb, 3, 'The inside film holds at 0.0025191879 and the steel at 0.000540611570 on every build, while the outside film goes from 0.0028828065 to 0.0022143296.'),
  ('flowassurance', 'beginner', 'final', null, 24, 'What does the first quarter inch of foam wall do on the published pipe, and why can no later inch repeat it?', '["It divides the coefficient by 22.61753379, and no later inch repeats it because a layer resistance goes as ln(Do/Di) and equal thickness added further out is less log.", "It divides the coefficient by 22.61753379, and later inches cannot repeat it because the foam conductivity rises with wall thickness.", "It divides the coefficient by 1.28791107, and later inches do better as the share climbs.", "It divides the coefficient by 79.39290539, which is the whole of what any foam can buy."]'::jsonb, 0, 'The first quarter inch is ln(7.125 / 6.625) at 0.0727593543 against ln(16.625 / 16.125) at 0.0305367239 out at the surface, a ratio of 2.38268370.'),
  ('flowassurance', 'beginner', 'final', null, 25, 'Which sweep row proves that thickness on its own is not insulation?', '["The 16.625 in row, where 5.0000 in of syntactic foam still leaves a coefficient of 0.3860878878 Btu/(hr ft2 degF) despite the foam carrying 99.741999 percent of the stack it sits in.", "The bare row at 6.625 in, where a wall of 0.0000 in leaves the coefficient at 105.9799311355 and the foam share at 0.000000 percent, which is the baseline every other row is measured against.", "The concrete weight coat at k 0.9000, 2.0 in thick, which leaves the coefficient at 12.1285554677 Btu/(hr ft2 degF).", "The aerogel row, which is thin and good."]'::jsonb, 2, 'The concrete layer resistance is 0.0466526625 against 0.4665266247 for the same 2.0 in of syntactic foam.'),
  ('flowassurance', 'beginner', 'final', null, 26, 'Why does the coefficient improve by 7.42733831 when the layer resistance improved by exactly 7.50000000?', '["Because the aerogel build carries a larger coated outside diameter, so its coefficient is expressed against a bigger area than the syntactic foam build and the two ratios are separated by the reference.", "Because the films and the steel wall are still in the stack and none of them moved with the conductivity.", "Because a layer resistance is inverse in conductivity while a coefficient is inverse in its square root, which is why the coefficient ratio is always the smaller of the two on any pipe.", "Because the two builds are sweep points rather than published cases."]'::jsonb, 1, 'The layer resistance is exactly inverse in k, at 3.4989496854 against 0.4665266247, but a coefficient carries terms the material never touched.'),
  ('flowassurance', 'beginner', 'final', null, 27, 'Where does the foam sweep say a coating should stop?', '["At the point where the foam share passes 99.421867 percent, past which the rest of the stack is small enough that further wall cannot change the coefficient by a useful amount on any line.", "At the 8.625 in row, since that row is the published build and the one the golden coefficients were cut on rather than any of the derived sweep points around it.", "At the row where the marginal ratio first falls below 1.28791107, which is where each further inch of wall starts returning less than the inch before it did.", "Nowhere, because the module prices no material and returns a coefficient for any wall typed into it."]'::jsonb, 3, 'Where a coating stops being worth its cost is a question about money and installation, and nothing in this module has an opinion on it.'),
  ('flowassurance', 'beginner', 'final', null, 28, 'The still water build and the shut in build both change one film on the published insulated pipe. Which one moves the answer further?', '["The shut in bore, which takes the coefficient to 1.0580538200 against 1.3163448815 for still water outside.", "Still water, which raises a film resistance by more than four times, and a term multiplied by four moves a coefficient further than a term multiplied by any smaller factor could.", "Neither, because both films carry under one percent of the stack.", "The shut in bore, but only because it is a published case."]'::jsonb, 0, 'The bore side film rises to 0.1259593944 and takes 21.16107640 percent of the stack, while the outside film in still water reaches 0.0088573186 at 1.85127692 percent.'),
  ('flowassurance', 'beginner', 'final', null, 29, 'A trench is priced per foot of digging. What does the resistance do?', '["It arrives by the foot until the argument 2H/D reaches one, after which the shape factor is flat and further cover adds nothing at all to the term, which is why the sweep stops at 20.000000 ft.", "It does not arrive by the foot. Doubling the depth from 1.000000 ft to 2.000000 ft moves the shape factor by only 1.42729466.", "It arrives by the foot throughout, which is why the ground resistance column and the depth column in the sweep are in exact proportion to one another across the whole table.", "It falls with depth, because the seabed above a deep trench is colder."]'::jsonb, 1, 'From 10.000000 ft to 20.000000 ft the same doubling is worth 1.17253653, and no return from the module warns anybody about the difference.'),
  ('flowassurance', 'beginner', 'final', null, 30, 'What does the ground term assume about the soil, and what does the module check?', '["One uniform conductivity everywhere, checked against the two catalog entries so that a value outside the range between them is returned with a note attached to the ground term in the resistances array.", "A backfill conductivity and a native soil conductivity entered separately, with the module blending the two across the trench profile and reporting the blend it used in the returned object.", "A conductivity that may vary with depth, resolved by the shape factor, which integrates the soil column above the pipe and returns the effective value it arrived at.", "One uniform conductivity everywhere, and nothing at all is checked."]'::jsonb, 3, 'One k stands for backfill and native soil, for the wet layer and the dry one, and the function returns a resistance to ten places for whichever figure it is given.'),
  ('flowassurance', 'beginner', 'final', null, 31, 'The published trench at 4.0 ft is read to the top of pipe instead of the centreline, so 4.359375 ft is what was meant. How large is that mistake here, and where would it be larger?', '["2.784925 percent here, and larger on a deep line, because the acosh argument grows with depth and a fixed offset in the depth therefore carries more weight the deeper the trench is cut.", "Half a coated diameter applied straight to the coefficient, so the size of the error is the same fraction on every line and depends only on the ratio of the coated diameter to the trench depth.", "2.784925 percent here, and larger on a shallow line where the shape factor is still steep.", "It is not a mistake, because the module reads depth to the top of pipe."]'::jsonb, 2, 'At the published depth 2H/D is 11.13043478 where acosh is nearly flat, against a factor of 1.42729466 between 1.000000 ft and 2.000000 ft of cover.'),
  ('flowassurance', 'beginner', 'final', null, 32, 'The published trench returns 0.4112572083 hr ft degF/Btu per foot. What would the same call return for a line carrying nothing at all?', '["The same 0.4112572083, because a ground resistance is a shape factor over a conductivity and knows nothing whatever about what is inside the pipe.", "A larger figure, because an empty line sits at the seabed temperature along its whole length and a shape factor derived for an isothermal cylinder returns more resistance as the difference driving heat across it falls away.", "A NaN, since a trench cannot be resolved without a fluid density in the call.", "Zero, since there is no heat leaving a line with nothing in it."]'::jsonb, 0, 'The term is two lengths and a conductivity, and the module has no route from the contents of a pipe into the ground term at any point.'),
  ('flowassurance', 'beginner', 'final', null, 33, 'What is the argument of the inverse hyperbolic cosine in the ground term, and what fixes its floor?', '["2H/D, floored where the argument reaches 2.78260870 at 1.000000 ft of cover, past which the shape factor grows like a logarithm and stops repaying any further depth at all.", "2H/D, floored at 1.00000000 where H equals half the coated outside diameter, which on 8.625 in is 0.35937500 ft.", "The depth divided by the soil conductivity, floored where the conductivity reaches the wet soil catalog value of 1.2000 Btu/(hr ft degF) and the trench stops behaving as a resistance at all.", "H over D, floored at 0.5, which is the pipe resting on the seabed."]'::jsonb, 1, 'Below that floor the argument falls under 1, acosh has no real value, and 0.30 ft on the published coated diameter gives 2H/D of 0.83478261.'),
  ('flowassurance', 'beginner', 'final', null, 34, 'The published trench is driven from 4.000000 ft to 20.000000 ft of cover. What happens to the ground share?', '["It reaches 100.00000000 percent, because a trench deep enough eventually dominates any stack it is added to and the terms inside the pipe become negligible against it at that depth.", "It falls, because the ground resistance rises more slowly than the total does and a share is a resistance divided by a total that is growing faster than its numerator.", "It reaches only 56.982867 percent, from 46.571938 percent, while the coefficient goes from 0.7132000377 to 0.5742267291.", "It does not move, because a share belongs to a build."]'::jsonb, 2, 'Cover added at 10.000000 ft is the flattest part of the curve, and the ground resistance runs only from 0.4112572083 to 0.6249732901 over that whole drive.'),
  ('flowassurance', 'beginner', 'final', null, 35, 'What is a mass per foot for, in this module?', '["It is the figure a lay barge works to, so that a line can be checked against the tension the installation vessel can hold as it is paid out over the stinger.", "It is the quantity a cooldown reports as its answer, since a shutdown study is quoted as the mass of fluid that has to be displaced before the line can be restarted safely.", "It is the term a coefficient is divided by, since a heat leak per square foot has to be normalised onto the material it is leaking out of before it can be carried into an arrival.", "It is an intermediate, computed so that a specific heat can turn it into a heat capacity."]'::jsonb, 3, 'Nobody reports lbm/ft as a flow assurance result, and every mistake made building one arrives later, in hours, wearing the units of an answer.'),
  ('flowassurance', 'beginner', 'final', null, 36, 'The published pipe carries 18.9921056882 lbm/ft of steel and 11.0344753586 lbm/ft of contents. Which of the two holds more heat?', '["The contents, at 72.534444 percent of the M Cp, because Cp 0.50 against Cp 0.11 is a wider gap than the masses opened.", "The steel, at 1.72116073 times the contents mass.", "They are equal once both specific heats are applied.", "The steel, because it is the denser of the two materials."]'::jsonb, 0, 'The contents heat capacity is 5.5172376793 and the steel 2.0891316257 Btu/(ft degF), for a total of 7.6063693050.'),
  ('flowassurance', 'beginner', 'final', null, 37, 'A contents mass is entered using a stock tank density rather than a density at line conditions. What comes back?', '["A NaN, because the helper compares the density supplied against the range it holds for a produced fluid and refuses anything that falls outside it before any area is multiplied at all.", "A clean answer in the right units describing a fluid the line is not carrying.", "The correct mass, since a contents mass is a geometric quantity and the density only sets the units the answer is expressed in rather than its magnitude.", "A note on the returned object naming the density as the field it could not check."]'::jsonb, 1, 'A density is the one input a contents mass cannot check, and the return is a bare number with nowhere to put a warning in any case.'),
  ('flowassurance', 'beginner', 'final', null, 38, 'A gas line and an oil line are both shut in. Which term is the heat store in each?', '["The contents on both, because a fluid always carries more heat than the wall around it once the specific heat of a hydrocarbon is set against the specific heat of a carbon steel.", "The steel on both, because the steel outweighs the contents on any pipe whose bore is smaller than its coated outside diameter, which is every pipe in this course.", "The steel on the gas line and the contents on the oil line.", "The coating on both, because it carries the resistance."]'::jsonb, 2, 'On TEACHING LINE AKASO SPUR the contents carry 27.263524 percent of what the two slots see, against 72.534444 percent on the published liquid filled case.'),
  ('flowassurance', 'beginner', 'final', null, 39, 'A cooldown is run with both masses returning a NaN. What comes back?', '["Hours computed on a heat capacity of zero, which come back as a very small positive number with ok true and a station table that reaches the target within the first interval of the event.", "Hours carrying a NaN, because a NaN entered into the total propagates through the division and arrives at the answer as a NaN that the caller can at least detect on inspection.", "The same answer as one good mass and one NaN, at 1.2806433091 hr, since the guard is written on the total and both routes reduce that total to the same value in the end.", "A refusal, because the total heat capacity reaches zero and the guard fires."]'::jsonb, 3, 'The guard is on the total rather than on either slot, which is why one bad mass out of two returns 1.2806433091 hr with ok true and no note.'),
  ('flowassurance', 'beginner', 'final', null, 40, 'Which two habits catch the two failures this module cannot catch for you?', '["Counting the terms in the resistances array, and checking both masses before handing them over.", "Reading the shares before the coefficient, and quoting the total resistance, since a share column that sums cleanly and a total that matches its own array are what a reader can actually verify.", "Recording the boundary first, and using the catalog defaults.", "Refining the profile, and quoting more figures."]'::jsonb, 0, 'A swallowed trench returns the exposed answer with ok true and no note, and a cooldown handed one NaN mass is short by 72.534444 percent with ok true and no note.'),
  ('flowassurance', 'beginner', 'final', null, 41, 'What can be said about a line once the Associate tier is finished with it, and what cannot?', '["What temperature arrives at the far end can be said, since the arrival follows from the coefficient and the two boundary temperatures, and what cannot be said is how long the line has after a shutdown.", "How hard heat leaves per square foot per degF can be said. What temperature arrives at the far end cannot.", "Both can be said, once the reference diameter has been carried with the coefficient, because the arrival is a closed form built on nothing but the coefficient and the geometry of the pipe.", "Neither can be said until the hydrate boundary is supplied."]'::jsonb, 1, 'Rate, time and temperature are where the stack hands over, and a coefficient is part of both later answers rather than either one.'),
  ('flowassurance', 'beginner', 'final', null, 42, 'Somebody reports a coefficient, a share column that sums to 100.00000000 percent, and two masses. What single line is still missing from the report?', '["The relative difference against the golden route, which is what tells a reader whether the coefficient was computed in field units or converted out of the SI the oracle works in throughout.", "The number of stations the profile was resolved on, since the arrival is read off that table and a coarse table interpolates between points rather than computing at them.", "Which layers went nowhere, because a stack of five terms and a mass of two is a fact about the answer.", "The ambient temperature, which no part of the stack records."]'::jsonb, 2, 'Two people can lump a coating differently and both returns look identical, which is why what was lumped where belongs beside the answer.');
